import {naturalForm,presetForm,boundary} from './nail-form.js';
export function nailSilhouette(name){const form=presetForm(naturalForm(),name==='custom'?'almond':name,'L'),points=boundary(form),d=points.map(([x,y],i)=>`${i?'L':'M'}${(5+x*40).toFixed(2)} ${(5+y*36).toFixed(2)}`).join(' ')+'Z';return `<svg viewBox="0 0 50 90" aria-hidden="true"><path d="${d}" fill="#e9d4c855" stroke="#967d68" stroke-width="1.2" ${name==='custom'?'stroke-dasharray="3 2"':''}/><path d="M17 19Q16 11 24 10" fill="none" stroke="#fff8" stroke-width="2"/>${name==='custom'?'<circle cx="25" cy="81" r="2" fill="#b77961"/>':''}</svg>`;}
